import React from 'react';
import { Link } from 'react-router-dom';

export default function Recursos(){
  return (
    <div className="min-h-screen flex items-center justify-center px-6 py-12 bg-gradient-to-b from-white to-gray-50">
      <div className="max-w-2xl w-full bg-white rounded-xl shadow-lg p-8 text-center">
        <h2 className="text-2xl font-semibold mb-4">Recursos</h2>
        <p className="text-gray-600 mb-6">Aquí puedes enlazar a tus recursos: playlists, descargas, cursos o redes.</p>
        <ul className="text-left">
          <li>- Recurso 1</li>
          <li>- Recurso 2</li>
          <li>- Recurso 3</li>
        </ul>
        <div className="mt-6">
          <Link to="/" className="text-sm text-primary hover:underline">Volver</Link>
        </div>
      </div>
    </div>
  )
}
